record.field:
# Read auth parameter keys from remote.connection_params JSON
remote = self.remote_id
cfg = {}
try:
    cfg = json.loads(remote.connection_params or '{}')
except Exception:
    cfg = {}
username = (cfg.get('username') or '').strip()
password = (cfg.get('password') or '').strip()
if not username or not password:
    raise Exception("Missing Batchline credentials: set username/password in connection_params.")
url = (base_url or '').rstrip('/') + '/token'
auth_data = {
    'grant_type': 'password',
    'username': username,
    'password': password,
}
headers = {
    'Content-Type': 'application/x-www-form-urlencoded',
}
resp = request_retry('POST', url, data=auth_data, headers=headers)
if resp.status_code >= 400:
    raise Exception("Login failed: %s %s" % (resp.status_code, resp.text))
try:
    j = resp.json() or {}
except ValueError:
    raise Exception("Login response is not valid JSON: %s" % resp.text)
token = j.get('access_token') or ''
if not token:
    raise Exception("Login OK but no 'access_token' in response.")
bag['token'] = token

# Action A: build sensors plan (robust JSON parsing)
Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
today_str = fields.Date.today()
condition = [
    ('remotecontrol_params','!=',False),
    ('device_id.remotecontrol_id', '=', Remote.id)
]
if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))
sensors = Sensor.search(condition)
# Optimize: build map of sensor_id -> most recent reading (single query)
last_readings_map = {}
if sensors:
    sensor_ids = [s.id for s in sensors]
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for row in cr.fetchall():
        last_readings_map[row[0]] = row[1]
# Now iterate sensors using the map
plan = []
for sensor in sensors:
    device = sensor.device_id
    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}
    sensor_tag = (sensor_cfg.get('tag') or '').strip()
    if sensor_tag:
        try:
            device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
        except Exception:
            device_cfg = {}
        device_id = (device_cfg.get('device_id') or '').strip()
        if device_id:
            # Retrieve last_reading from map (no query per sensor)
            last_reading_time = last_readings_map.get(sensor.id)
            if last_reading_time:
                try:
                    initial_date = fields.Date.to_string(
                        fields.Datetime.from_string(last_reading_time))
                except Exception:
                    initial_date = str(last_reading_time)[:10]
            else:
                start_cfg = (sensor_cfg.get('start_date') or device_cfg.get('start_date'))
                if start_cfg:
                    initial_date = start_cfg[:10]
                else:
                    year_str = today_str[:4]
                    initial_date = '%s-01-01' % year_str
            plan.append({
                'sensor_id': sensor.id,
                'device_id': device.id,
                'device_batchline_id': device_id,
                'sensor_tag': sensor_tag,
                'initial_date': initial_date,
            })
bag['sensors_plan'] = plan

Remote=self.remote_id
token=bag.get("token")
if not token:
    raise Exception(u"Missing Batchline token in bag")
base_url=(bag.get(u'base_url') or Remote.base_url or u'').rstrip(u'/')+u'/api'
headers={u'Authorization':u'Bearer %s'%token,u'Accept':u'application/json'}

resp=request_retry(u'GET', base_url+u'/elementos', headers=headers, timeout=timeout)
if resp.status_code>=400:
    raise Exception(u"Error fetching elements: %s %s"%(resp.status_code, resp.text))
elements=resp.json() or []
elements_list=[]
for e in elements:
    if not isinstance(e, dict):
        continue
    identificador=e.get(u'Identificador') or e.get(u'id') or u'Elemento sin identificador'
    descripcion=e.get(u'Descripcion') or e.get(u'descripción') or e.get(u'name') or u'Sin descripción'
    tags=e.get(u'Tags') or []
    tag_list=[]
    for t in tags:
        if not isinstance(t, dict):
            continue
        tag_list.append({
            u'nombre': t.get(u'Nombre') or t.get(u'name') or u'Sin nombre',
            u'unidad': t.get(u'Unidad') or t.get(u'unidad') or u''
        })
    elements_list.append({
        u'identificador': identificador,
        u'descripcion': descripcion,
        u'tags': tag_list
    })
summary={
    u'total_elements': len(elements_list),
    u'executed_at': fields.Datetime.now()
}
data={
    u'elements': elements_list,
    u'summary': summary
}
json_str=json.dumps(data, ensure_ascii=False, indent=2)
encoded=base64.b64encode(json_str.encode(u'utf-8'))
fname=u'batchline_elements_%s.json'%fields.Datetime.now().replace(u':',u'').replace(u'-',u'').replace(u' ',u'_')
att=env[u'ir.attachment'].create({
    u'name': fname,
    u'datas_fname': fname,
    u'datas': encoded,
    u'mimetype': u'application/json',
    u'res_model': u'remotecontrol',
    u'res_id': Remote.id
})
Remote.message_post(
    body=u'[Batchline] Imported %s elements'%(len(elements_list)),
    attachment_ids=[att.id]
)
bag.clear()
bag[u'total_elements']=len(elements_list)
bag[u'attachment_id']=att.id
bag[u'attachment_name']=fname

# Build pressure sensors plan
Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
today_str = fields.Date.today()
condition = [
    ('remotecontrol_params','!=',False),
    ('device_id.remotecontrol_id', '=', Remote.id)
]
if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))
sensors = Sensor.search(condition)
# Optimize: build map of sensor_id -> most recent reading (single query)
last_readings_map = {}
if sensors:
    sensor_ids = [s.id for s in sensors]
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for row in cr.fetchall():
        last_readings_map[row[0]] = row[1]
# Now iterate sensors using the map
plan = []
for sensor in sensors:
    device = sensor.device_id
    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}
    sensor_type = (sensor_cfg.get('sensor_type') or '').strip()
    # Only process pressure sensors
    if sensor_type:
        try:
            device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
        except Exception:
            device_cfg = {}
        hidrante = (device_cfg.get('hidrante') or '').strip()
        electronica = device_cfg.get('electronica')
        canal = device_cfg.get('canal')
        if hidrante and electronica is not None and canal is not None:
            # Retrieve last_reading from map (no query per sensor)
            last_reading_time = last_readings_map.get(sensor.id)
            if last_reading_time:
                try:
                    initial_date = fields.Date.to_string(
                        fields.Datetime.from_string(last_reading_time))
                except Exception:
                    initial_date = str(last_reading_time)[:10]
            else:
                start_cfg = (sensor_cfg.get('start_date') or device_cfg.get('start_date'))
                if start_cfg:
                    initial_date = start_cfg[:10]
                else:
                    year_str = today_str[:4]
                    initial_date = '%s-01-01' % year_str
            plan.append({
                'sensor_id': sensor.id,
                'device_id': device.id,
                'hidrante': hidrante,
                'electronica': electronica,
                'canal': canal,
                'initial_date': initial_date,
            })
bag['pressure_sensors_plan'] = plan
